$$$ Royal - Mashup (212).warp:
shader_body
{
    float2 d = texsize.zw*4;
    float3 dx = ( 2*GetBlur1(uv+float2(1,0)*d)-2*GetBlur1(uv-float2(1,0)*d) );
    float3 dy = ( 2*GetBlur1(uv+float2(0,1)*d)-2*GetBlur1(uv-float2(0,1)*d) );
float2 dz = -float2(dx.x,dy.x)*texsize.zw*1;

//ret = GetPixel(uv);
ret = 0;
ret.x = tex2d(sampler_fw_main,uv - dz).x - 0.0 - (GetBlur3(uv).x-GetBlur1(uv+dz).x) ;

ret *= max(treb,max(bass,mid));

}

