$$$ Royal - Mashup (447).warp:
shader_body
{
    float2 d = texsize.zw*4;
    float3 dx = ( 2*GetBlur1(uv+float2(1,0)*d)-2*GetBlur1(uv-float2(1,0)*d) );
    float3 dy = ( 2*GetBlur1(uv+float2(0,1)*d)-2*GetBlur1(uv-float2(0,1)*d) );
float2 dz = -float2(dx.x,dy.x)*texsize.zw*1;

//ret = GetPixel(uv);
ret = 0;
ret.x = tex2d(sampler_fw_main,uv - dz).x - 0.0 - (GetBlur3(uv).x-GetBlur1(uv+dz).x) ;

ret *= max(treb,max(bass,mid));

}

$$$ Royal - Mashup (447).comp:
shader_body
{
    float rad_lq = rad * length(texsize.xy)*0.5;
    float ang_lq = ang;
    float2 uv_temp1 = (uv - 0.5) * texsize.xy;
    float rad_hq = length(uv_temp1);
    float ang_hq = atan2(-uv_temp1.y, uv_temp1.x);

    float2 uv2 = (uv - 0.5);
    float rad2 = rad_lq*0.75;
    float ang2 = ang_lq * M_INV_PI_2;

        // ROTATION OVER TIME
        ang2 += time*0.025;   //rotate over time

        // FIN TYPE
        float fins = 8;//3 + floor(rand_preset.z*5.95);
        ang2 = cos(ang2*M_PI_2*fins) * 0.023;


    ang2 *= M_PI_2;
    uv2 = 0.5 + rad2*float2(cos(ang2),sin(ang2))*texsize.zw;

    ret = tex2D(sampler_main, uv2).xyz;
    ret *= 1.0; // a little bit of overbright
}

