ob_g=0.3 + 0.3*sin(time*0.897)+0.3*mv_b;
ob_b=0.2+0.5*mv_r;
treb_effect = max(max(treb, treb_att)-1.2,0);
mid_effect = max(max(mid,mid_att)-1.2,0);
ib_r = 1 - ob_b;
ib_g = 1- mv_g;
ib_b = 0.5*mv_b + 0.5*ob_b;
ib_a = if(above(treb_effect,0), if(above(mid_effect,0),1,0),0);

