float2 d, uv_y;
float3 dx, dy;
shader_body
{

    d = texsize.zw*18;
    dx = ( GetBlur1(uv+float2(1,0)*d)-GetBlur1(uv-float2(1,0)*d) );
    dy = ( GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) );

float3 base = GetPixel(uv);
float emboss = (-dx + dy + 1);

    d = texsize.zw*2;
    dx = ( GetBlur1(uv+float2(1,0)*d)-GetBlur1(uv-float2(1,0)*d) );
    dy = ( GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) );

float grad = length(float2(dx.x,dy.x));

ret = lerp( float3(0.5,0.3,0)*base.x*emboss,
            float3(8,7,0)*grad,
            grad
          ); 

 float zoom =1.81;
 float2 c = float2(0.448+q9,0.701+q10);
 float2 my_uv2 = (uv-0.5)*zoom;
 my_uv2 = float2(my_uv2.x*my_uv2.x - my_uv2.y*my_uv2.y, 2*my_uv2.x*my_uv2.y) + c;
 my_uv2 = 1.0 - abs( frac( my_uv2 * 0.5 ) * 2.0 - 1.0 ); // Eo.S' mirror code

 float3 julia = GetPixel(my_uv2);



ret = lerp(ret, float3(0.32,0.06,0.04), julia.z*4);
ret = lerp(ret, 1, base.y);
}

