    float3 dy = ( 2*GetBlur1(uv + float2(0,1)*d) - 2*GetBlur1(uv-float2(0,1)*d) )*0.5;

    float2 dither_uv = uv_orig*texsize.xy*texsize_noise_lq.zw * 1.2 + rand_frame.xy;

    float2 my_uv =  lerp(uv_orig,uv,1) ;
    float2 uv_x= frac(my_uv + float2(dx.x,dy.x)*texsize.zw  *4);
    float2 uv_y= frac(my_uv + float2(dx.y,dy.y)*texsize.zw  *4);
    float2 uv_z= frac(my_uv + float2(dx.z,dy.z)*texsize.zw  *4);
    ret.x = GetPixel(uv_x).x - (2*GetPixel(uv_x) - 2*GetBlur3(uv_x)).x  * 0.01;
    ret.y = GetPixel(uv_y).y - (2*GetPixel(uv_y) - 2*GetBlur3(uv_y)).y  * 0.01;
    ret.z = GetPixel(uv_z).z - (2*GetPixel(uv_z) - 2*GetBlur3(uv_z)).z  * 0.01;

    ret += (tex2D(sampler_noise_lq, dither_uv).xyz-0.5) *0.008;
ret -= ret.yzx*0.1 - 0.014;

}

