uv3=abs(frac(uv3+.5)-.5) ;

    neu =  GetPixel (uv3) + 2*GetBlur1(uv3);

    ret1 = max(ret1*.9,neu*inten);
n++;
}

ret = .5*ret1 + 0.5*float3(0,0,.3)*(.5+uv.y) ;
//ret = GetPixel(uv+.5);
