shader_body 
{ 
    //flexi's bump map effect

    float2 d = texsize.zw*4; 
    float3 dx = ( GetBlur1(uv + float2(1,0)*d) - GetBlur1(uv-float2(1,0)*d) ); 
    float3 dy = ( GetBlur1(uv + float2(0,1)*d) - GetBlur1(uv-float2(0,1)*d) ); 
    float2 light_pos = float2(0.5,0); 
    float3 col = float3(4,4,4); 
    float c = 4; 
    float dd = 16; 
    float3 plastic; 
    plastic.x = col.x/(1+dd*pow(length( uv - float2(dx.x,dy.x)*c - light_pos),0.5)); 
    plastic.y = col.y/(1+dd*pow(length( uv - float2(dx.y,dy.y)*c - light_pos),0.5)); 
    plastic.z = col.z/(1+dd*pow(length( uv - float2(dx.z,dy.z)*c - light_pos),0.5)); 

    ret = plastic*GetPixel(uv); 
    ret *= 3;
}

