{

   float3 Color1= float3(q10, q11, q12);
   float3 Color2= float3(q13, q14, q15);
   float3 Color3= float3(1, 1, 1);
   float3 Color4= float3(q16, q17, q18);
   float3 Color5= float3(q19, q20, q21);
   float3 Color6= float3(q22, q23, q24);


   float2x2 rot = {q5, q6,
               -q6, q5};


  uv -= 0.5;
  uv = mul(rot,uv);   

   float inc;

   if(uv.x > 0){
     inc = -q4; 
   }else{
     inc = q4;
   } 
   uv = float2((uv.y/(0.02+length(uv)*q5)),
               (uv.x/(0.02+length(uv)*q7)));  
   uv.x = uv.x + inc;
   uv.y = uv.y + inc;

   uv += 0.5;


   float3 uvx =  float3(uv, time*0.1);   


  float4 noisevec = tex3D(sampler_noisevol_lq, uvx);
  float intensity = abs(noisevec.x - 0.25) +
                    abs(noisevec.y - 0.125) +
                    abs(noisevec.z - 0.0625) +
                    abs(noisevec.w - 0.03125);


  intensity = sin(intensity * 6.0)*0.5 + 0.5;
  ret = lerp(Color1, Color2, intensity)*.5;

  noisevec = tex3D(sampler_noisevol_hq, uvx);
  intensity = abs(noisevec.x - 0.25) +
                    abs(noisevec.y - 0.125) +
                    abs(noisevec.z - 0.0625) +
                    abs(noisevec.w - 0.03125);

  intensity = sin(intensity * 6.0)*0.5 + 0.5;
  ret += lerp(Color3, Color4, intensity)*0.5;

  noisevec = tex3D(sampler_noisevol_lq, uvx*0.4);
  intensity = abs(noisevec.x - 0.25) +
                    abs(noisevec.y - 0.125) +
                    abs(noisevec.z - 0.0625) +
                    abs(noisevec.w - 0.03125);


  intensity = tan(intensity * 5.0)*0.5 + 0.5;
  ret -= lerp(Color5, Color6, intensity); 
  ret -= tex2D(sampler_main, uv);
